import ServiceCards from "@/components/ServiceCards";
import serviceAreas from "@/data/serviceAreas.json";
import RoavioLayout from "@/layout/RoavioLayout";

export default function ServiceAreasPage() {
  const cards = serviceAreas.map((area) => ({
    name: area.name,
    image: area.image,
    description: area.description,
    href: `/service-areas/${area.city}`,
  }));

  return (
    <RoavioLayout>
      <section className="tour-grid-section section-padding">
        <div className="container">
          <h1 className="mb-4">Explore India with a Local Tour Guide</h1>
          <ServiceCards cards={cards} />
        </div>
      </section>
    </RoavioLayout>
  );
}


